function Logo(){return <div className="logo"><div className="logoMark"><span/><span/><span/></div><div><b>Smart Wealth</b><small>ADVISOR</small></div></div>}
function Sparkline({down=false}:{down?:boolean}){return <svg className="spark" viewBox="0 0 130 44" aria-hidden><path d={down?'M2 8 C18 6 22 24 38 19 S58 12 69 26 S91 17 100 30 S118 26 128 36':'M2 37 C14 34 21 39 31 27 S51 29 62 20 S81 25 91 13 S110 17 128 4'} fill="none" stroke={down?'#dd665f':'#48a996'} strokeWidth="2.5" strokeLinecap="round"/><path d={down?'M2 8 C18 6 22 24 38 19 S58 12 69 26 S91 17 100 30 S118 26 128 36 L128 44 L2 44Z':'M2 37 C14 34 21 39 31 27 S51 29 62 20 S81 25 91 13 S110 17 128 4 L128 44 L2 44Z'} fill={down?'url(#r)':'url(#g)'}/><defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#48a996" stopOpacity=".22"/><stop offset="1" stopColor="#48a996" stopOpacity="0"/></linearGradient><linearGradient id="r" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#dd665f" stopOpacity=".18"/><stop offset="1" stopColor="#dd665f" stopOpacity="0"/></linearGradient></defs></svg>}
function Metric({title,value,delta,icon:Icon,down=false}:{title:string,value:string,delta:string,icon:any,down?:boolean}){return <div className="metric card"><div className="metricTop"><div className="metricIcon"><Icon size={19}/></div><span className="period">This month</span></div><p>{title}</p><div className="metricRow"><div><strong>{value}</strong><span className={down?'negative':'positive'}>{down?<ArrowDownRight/>:<ArrowUpRight/>}{delta}</span></div><Sparkline down={down}/></div></div>}
function Donut({total,profile}:{total:number;profile:Profile}){return <div className="donut" style={{background:'conic-gradient(#3267e3 0 38%,#6e9af2 38% 54%,#4cb8a7 54% 76%,#d39c45 76% 88%,#aeb8c8 88% 96%,#7e68c7 96%)'}}><div><b>{fmt(total,profile)}</b><span>Invested</span></div></div>}
function PerformanceChart(){return <div className="chart"><div className="axis"><span>$380K</span><span>$340K</span><span>$300K</span><span>$260K</span><span>$220K</span></div><svg viewBox="0 0 620 190" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#3267e3" stopOpacity=".22"/><stop offset="1" stopColor="#3267e3" stopOpacity="0"/></linearGradient></defs><g className="grid"><path d="M0 10H620M0 52H620M0 95H620M0 137H620M0 180H620"/></g><path className="area" d="M0 162 C35 154 49 159 76 147 S121 133 145 141 S189 118 215 125 S253 96 290 106 S329 86 362 94 S404 69 430 80 S466 51 493 62 S532 43 557 49 S595 20 620 26 L620 190 L0 190Z"/><path className="line" d="M0 162 C35 154 49 159 76 147 S121 133 145 141 S189 118 215 125 S253 96 290 106 S329 86 362 94 S404 69 430 80 S466 51 493 62 S532 43 557 49 S595 20 620 26"/><circle cx="620" cy="26" r="5"/></svg><div className="months"><span>Oct</span><span>Dec</span><span>Feb</span><span>Apr</span><span>Jun</span><span>Aug</span><span>Oct</span></div></div>}

function Dashboard({ar,setTab,profile}:{ar:boolean,setTab:(t:Tab)=>void;profile:Profile}){const t=ar?copy.ar:copy.en;const [transactions,setTransactions]=useState<Transaction[]>([]);useEffect(()=>{const load=()=>loadTransactions().then(setTransactions).catch(()=>setTransactions([]));load();window.addEventListener('swa-data-updated',load);return()=>window.removeEventListener('swa-data-updated',load)},[]);const month=new Date().toISOString().slice(0,7),monthTx=transactions.filter(x=>x.date.startsWith(month));const txIncome=monthTx.filter(x=>x.kind==='income').reduce((s,x)=>s+x.amount,0),txExpenses=monthTx.filter(x=>x.kind==='expense').reduce((s,x)=>s+x.amount,0);const income=txIncome||profile.income,expenses=txExpenses||profile.expenses;const nw=profile.netWorth;const surplus=income-expenses;const invested=Math.max(0,profile.capital+profile.savings);return <>
 <section className="welcome"><div><h1>{ar?'صباح الخير، ': 'Good morning, '}{profile.name} <span>👋</span></h1><p>{t.sub}</p></div><button className="primary" onClick={()=>setTab('Simulator')}><Sparkles size={17}/>{t.advisor}</button></section>
 <section className="metrics"><Metric title={t.net} value={fmt(nw,profile)} delta={ar?'من السجلات':'Recorded'} icon={Landmark}/><Metric title={t.cash} value={fmt(surplus,profile)} delta={`${profile.income?Math.max(0,surplus/profile.income*100).toFixed(0):0}% ${ar?'ادخار':'saved'}`} icon={TrendingUp} down={surplus<0}/><Metric title={ar?'إجمالي الديون':'Total debt'} value={fmt(profile.debt,profile)} delta={ar?'الرصيد الحالي':'Current balance'} icon={Coins} down={profile.debt>0}/><div className="score card"><div className="scoreRing"><span>—</span></div><div><p>{t.score}</p><strong>{ar?'غير مقيّم':'Not assessed'}</strong><small>{ar?'أكمل تقييم المخاطر':'Complete a risk assessment'}</small></div><Info size={16}/></div></section>
 <section className="gridMain"><div className="card performance"><div className="cardHead"><div><h2>{ar?'ملخص البيانات الفعلية':'Authoritative data summary'}</h2><p>{ar?'الأرقام أعلاه محسوبة من العمليات والالتزامات المحفوظة.':'The figures above are calculated from saved transactions and liabilities.'}</p></div></div><div className="emptyState"><ShieldCheck/><h3>{ar?'لا توجد عوائد سوق مفترضة':'No fabricated market returns'}</h3><p>{ar?'أضف مراكزك وأسعارها يدويًا في صفحة المحفظة لحساب القيمة والتوزيع.':'Add positions and user-entered prices in Portfolio to calculate value and allocation.'}</p><button className="outline" onClick={()=>setTab('Portfolio')}>{ar?'فتح المحفظة':'Open portfolio'}<ChevronRight/></button></div></div><div className="card allocation"><div className="cardHead"><div><h2>{ar?'الخطوات التالية':'Next steps'}</h2><p>{ar?'حسّن جودة التحليل بإكمال سجلاتك':'Improve analysis quality by completing your records'}</p></div></div><div className="miniEmpty"><ReceiptText/><b>{ar?'حدّث العمليات شهريًا':'Keep transactions current'}</b><span>{ar?'التوصيات والتقارير تعتمد فقط على البيانات المسجلة.':'Recommendations and reports use only recorded data.'}</span></div><button className="textBtn" onClick={()=>setTab('Transactions')}>{ar?'عرض العمليات':'View transactions'}<ChevronRight size={14}/></button></div></section>
 <section className="lowerGrid"><div className="card goals"><h2>{ar?'الأهداف':'Financial goals'}</h2><p>{ar?'تابع الأهداف والمساهمات المحفوظة.':'Track saved goals and contributions.'}</p><button className="outline" onClick={()=>setTab('Goals')}>{ar?'فتح الأهداف':'View goals'}<ChevronRight/></button></div><div className="card insights"><h2>{ar?'تحليلات وتوصيات':'Insights & recommendations'}</h2><p>{ar?'اعرض حالة نماذج التعلم الآلي والتوصيات القابلة للتفسير.':'View ML availability and explainable recommendations.'}</p><button className="outline" onClick={()=>setTab('Insights')}>{ar?'فتح التحليلات':'View insights'}</button></div><CashFlow t={t} profile={profile} income={income} expenses={expenses} ar={ar}/></section>
 </>}
function GoalsCard(){return <div className="card goals"><div className="cardHead"><div><h2>Financial goals</h2><p>Your path to what matters</p></div><button className="iconBtn" onClick={()=>act('Add a goal')}><Plus size={18}/></button></div><Goal icon={<Home/>} name="Home down payment" meta="$74,500 of $100,000" pct={75} color="#3267e3" date="Jun 2027"/><Goal icon={<ShieldCheck/>} name="Financial independence" meta="$218,000 of $1.2M" pct={18} color="#4cb8a7" date="Age 48"/><Goal icon={<Globe2/>} name="World trip" meta="$11,200 of $18,000" pct={62} color="#d39c45" date="Dec 2027"/></div>}
function Goal({icon,name,meta,pct,color,date}:{icon:any,name:string,meta:string,pct:number,color:string,date:string}){return <div className="goal"><div className="goalIcon" style={{color,background:color+'16'}}>{icon}</div><div className="goalMid"><div><b>{name}</b><span>{date}</span></div><p>{meta}</p><div className="progress"><i style={{width:pct+'%',background:color}}/></div></div><strong>{pct}%</strong></div>}
function Insights({setTab}:{setTab:(t:Tab)=>void}){return <div className="card insights"><div className="cardHead"><div><span className="eyebrow"><Sparkles size={14}/> AI ADVISOR</span><h2>3 ways to improve your plan</h2></div></div><div className="insight"><span className="insightIcon blue"><TrendingUp/></span><div><b>Put idle cash to work</b><p>Moving $18,000 to a high-yield account could earn an extra $720/year.</p><button onClick={()=>act('Review cash opportunity')}>Review opportunity <ChevronRight/></button></div></div><div className="insight"><span className="insightIcon green"><ShieldCheck/></span><div><b>Your emergency fund is fully funded</b><p>You have 7.2 months of essential expenses covered.</p></div></div><button className="outline" onClick={()=>setTab('Simulator')}>View all insights</button></div>}
function CashFlow({t,profile,income,expenses,ar}:{t:any;profile:Profile;income:number;expenses:number;ar:boolean}){const savings=income-expenses;const max=Math.max(1,income,expenses,Math.abs(savings));return <div className="card cashflow"><div className="cardHead"><div><h2>{t.cash}</h2><p>{new Intl.DateTimeFormat(uiLocale(),{month:'long',year:'numeric'}).format(new Date())}</p></div><b>{ar?'مسجل':'Recorded'}</b></div><div className="bars"><div><span style={{height:`${Math.max(4,income/max*100)}%`}}/><span style={{height:`${Math.max(4,expenses/max*100)}%`}}/><span style={{height:`${Math.max(4,Math.abs(savings)/max*100)}%`}}/></div><div className="barLabels"><span>{t.income}<b>{fmt(income,profile)}</b></span><span>{t.expenses}<b>{fmt(expenses,profile)}</b></span><span>{t.savings}<b>{fmt(savings,profile)}</b></span></div></div><div className="savingRate"><span>Savings rate</span><b>{income?(savings/income*100).toFixed(1):0}%</b></div></div>}


const expenseCategories=['Housing','Food','Transport','Bills','Shopping','Health','Education','Entertainment','Debt','Other'];
const categoryAr:Record<string,string>={Housing:'السكن',Food:'الطعام',Transport:'المواصلات',Bills:'الفواتير',Shopping:'التسوق',Health:'الصحة',Education:'التعليم',Entertainment:'الترفيه',Debt:'الديون',Other:'أخرى',Salary:'الراتب',Business:'عمل خاص',Investment:'استثمار'};
async function loadTransactions():Promise<Transaction[]>{const r=await api<any>('/transactions?page=1&page_size=100&sort=occurred_on&order=desc');return r.items.map((x:any)=>({id:x.id,kind:x.kind,amount:Number(x.amount),category:x.category,date:x.occurred_on,description:x.description||'',recurring:x.recurring}))}
function TransactionsPage({profile,ar}:{profile:Profile;ar:boolean}){const [items,setItems]=useState<Transaction[]>([]),[show,setShow]=useState(false),[error,setError]=useState('');const [kind,setKind]=useState<'income'|'expense'>('expense'),[amount,setAmount]=useState(0),[category,setCategory]=useState('Food'),[date,setDate]=useState(new Date().toISOString().slice(0,10)),[description,setDescription]=useState('');const reload=()=>loadTransactions().then(setItems).catch(()=>setError(ar?'تعذر تحميل العمليات':'Could not load transactions'));useEffect(()=>{reload()},[]);const add=async()=>{if(amount<=0||!date)return;setError('');try{await api('/transactions',json('POST',{kind,amount,currency:profile.currency,occurred_on:date,description:description.trim(),category,recurring:false,tags:[]}));await reload();window.dispatchEvent(new Event('swa-data-updated'));setAmount(0);setDescription('');setShow(false)}catch(e){setError(e instanceof Error?e.message:'Could not save')}};const remove=async(id:string)=>{if(confirm(ar?'هل تريد حذف هذه العملية؟':'Delete this transaction?')){try{await api(`/transactions/${id}`,{method:'DELETE'});await reload();window.dispatchEvent(new Event('swa-data-updated'))}catch(e){setError(e instanceof Error?e.message:'Could not delete')}}};const month=new Date().toISOString().slice(0,7);const monthly=items.filter(x=>x.date.startsWith(month));const totalIncome=monthly.filter(x=>x.kind==='income').reduce((s,x)=>s+x.amount,0),totalExpense=monthly.filter(x=>x.kind==='expense').reduce((s,x)=>s+x.amount,0);return <PageWrap title={ar?'العمليات المالية':'Transactions'} sub={ar?'سجّل دخلك ومصروفاتك لبناء تحليل وتوقعات دقيقة.':'Record income and expenses to power accurate analysis and predictions.'}>{error&&<div className="card dataNeeded"><AlertTriangle/><p>{error}</p><button className="outline" onClick={reload}>{ar?'إعادة المحاولة':'Retry'}</button></div>}<div className="transactionSummary"><div className="card"><span>{ar?'دخل هذا الشهر':'This month income'}</span><b className="positive">{fmt(totalIncome,profile)}</b></div><div className="card"><span>{ar?'مصروفات هذا الشهر':'This month expenses'}</span><b className="negative">{fmt(totalExpense,profile)}</b></div><div className="card"><span>{ar?'صافي التدفق':'Net cash flow'}</span><b className={totalIncome-totalExpense>=0?'positive':'negative'}>{fmt(totalIncome-totalExpense,profile)}</b></div><button className="primary" onClick={()=>setShow(!show)}><Plus/>{ar?'إضافة عملية':'Add transaction'}</button></div>{show&&<div className="card transactionForm"><div className="kindSwitch"><button className={kind==='expense'?'active':''} onClick={()=>{setKind('expense');setCategory('Food')}}>{ar?'مصروف':'Expense'}</button><button className={kind==='income'?'active':''} onClick={()=>{setKind('income');setCategory('Salary')}}>{ar?'دخل':'Income'}</button></div><div className="transactionFields"><Field label={ar?'المبلغ':'Amount'}><input type="number" min="0" value={amount||''} onChange={e=>setAmount(+e.target.value)} placeholder="0"/></Field><Field label={ar?'التصنيف':'Category'}><select value={category} onChange={e=>setCategory(e.target.value)}>{(kind==='expense'?expenseCategories:['Salary','Business','Investment','Other']).map(x=><option key={x} value={x}>{ar?(categoryAr[x]||x):x}</option>)}</select></Field><Field label={ar?'التاريخ':'Date'}><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label={ar?'الوصف':'Description'}><input value={description} onChange={e=>setDescription(e.target.value)} placeholder={ar?'مثال: غداء العمل':'e.g. Business lunch'}/></Field></div><div className="formActions"><button className="outline" onClick={()=>setShow(false)}>{ar?'إلغاء':'Cancel'}</button><button className="primary" disabled={amount<=0} onClick={add}><Save/>{ar?'حفظ العملية':'Save transaction'}</button></div></div>}<div className="card transactionTable"><div className="cardHead"><div><h2>{ar?'سجل العمليات':'Transaction history'}</h2><p>{ar?`${items.length} عملية محفوظة`:`${items.length} saved transactions`}</p></div></div>{items.length===0?<div className="emptyState"><ReceiptText/><h3>{ar?'لا توجد عمليات بعد':'No transactions yet'}</h3><p>{ar?'أضف أول عملية ليبدأ التحليل الذكي والتنبؤ بالمصروفات.':'Add your first transaction to activate smart analytics and expense prediction.'}</p><button className="primary" onClick={()=>setShow(true)}><Plus/>{ar?'إضافة أول عملية':'Add first transaction'}</button></div>:<div className="tableScroll"><table><thead><tr><th>{ar?'التاريخ':'Date'}</th><th>{ar?'النوع':'Type'}</th><th>{ar?'التصنيف':'Category'}</th><th>{ar?'الوصف':'Description'}</th><th>{ar?'المبلغ':'Amount'}</th><th/></tr></thead><tbody>{items.map(t=><tr key={t.id}><td>{new Intl.DateTimeFormat(ar?'ar-EG':'en-US',{dateStyle:'medium'}).format(new Date(t.date+'T12:00:00'))}</td><td><span className={`typePill ${t.kind}`}>{t.kind==='income'?(ar?'دخل':'Income'):(ar?'مصروف':'Expense')}</span></td><td>{ar?(categoryAr[t.category]||t.category):t.category}</td><td>{t.description||'—'}</td><td className={t.kind==='income'?'positive':'negative'}>{t.kind==='income'?'+':'−'}{fmt(t.amount,profile)}</td><td><button className="deleteBtn" onClick={()=>remove(t.id)}><Trash2/></button></td></tr>)}</tbody></table></div>}</div></PageWrap>}

type BudgetMap=Record<string,number>;
function BudgetPage({profile,ar}:{profile:Profile;ar:boolean}){const suggested:BudgetMap={Housing:profile.income*.3,Food:profile.income*.15,Transport:profile.income*.1,Bills:profile.income*.1,Shopping:profile.income*.08,Entertainment:profile.income*.07,Savings:profile.income*.15,Emergency:profile.income*.05};const [budget,setBudget]=useState<BudgetMap>(suggested),[items,setItems]=useState<Transaction[]>([]),[saved,setSaved]=useState(false);const now=new Date();useEffect(()=>{Promise.all([api<any>(`/budgets/${now.getFullYear()}/${now.getMonth()+1}`).catch(()=>null),loadTransactions()]).then(([b,tx])=>{if(b)setBudget(Object.fromEntries(b.items.map((x:any)=>[x.category,Number(x.limit_amount)])));setItems(tx)})},[]);const save=async()=>{await api('/budgets',json('POST',{year:now.getFullYear(),month:now.getMonth()+1,currency:profile.currency,savings_target:budget.Savings||0,items:Object.entries(budget).filter(([k])=>k!=='Savings'&&k!=='Emergency').map(([category,limit_amount])=>({category,limit_amount,essential:['Housing','Food','Transport','Bills'].includes(category)}))}));setSaved(true);setTimeout(()=>setSaved(false),2200);window.dispatchEvent(new Event('swa-data-updated'))};const month=new Date().toISOString().slice(0,7);const spent:Record<string,number>={};items.filter(x=>x.kind==='expense'&&x.date.startsWith(month)).forEach(x=>spent[x.category]=(spent[x.category]||0)+x.amount);const total=Object.values(budget).reduce((s,x)=>s+x,0);return <PageWrap title={ar?'خطة الميزانية':'Budget plan'} sub={ar?'وزّع دخلك، تابع حدود الإنفاق، وعدّل الخطة بما يناسب أهدافك.':'Allocate income, track spending limits, and adapt the plan to your goals.'}><div className="budgetHero card"><div><span className="eyebrow"><PiggyBank/>{ar?'خطة شهرية ذكية':'SMART MONTHLY PLAN'}</span><h2>{ar?'كل جنيه له هدف واضح':'Give every unit of income a clear job'}</h2><p>{ar?'تم اقتراح التوزيع بناءً على دخلك الحالي، ويمكنك تعديل كل بند.':'Suggested from your current income. Every category remains editable.'}</p></div><div className="budgetTotal"><span>{ar?'المبلغ الموزع':'Allocated'}</span><b>{fmt(total,profile)}</b><small className={total<=profile.income?'positive':'negative'}>{total<=profile.income?(ar?'داخل حدود الدخل':'Within income'):(ar?'يتجاوز الدخل':'Over income')}</small></div></div><div className="budgetGrid"><div className="card budgetEditor"><div className="cardHead"><div><h2>{ar?'حدود الفئات':'Category limits'}</h2><p>{ar?'انقر على أي مبلغ لتعديله':'Edit any amount directly'}</p></div><button className="primary" onClick={save}><Save/>{saved?(ar?'تم الحفظ':'Saved'):(ar?'حفظ الخطة':'Save plan')}</button></div>{Object.entries(budget).map(([cat,limit])=>{const used=spent[cat]||0,pct=limit?Math.min(100,used/limit*100):0;return <div className="budgetRow" key={cat}><div><b>{ar?(categoryAr[cat]||({Savings:'الادخار',Emergency:'الطوارئ'} as any)[cat]||cat):cat}</b><span>{ar?'تم إنفاق':'Spent'} {fmt(used,profile)}</span></div><div className="budgetProgress"><i style={{width:pct+'%',background:pct>90?'#d85b57':pct>70?'#d39c45':'#3267e3'}}/></div><div className="budgetInput"><span>{profile.currency}</span><input type="number" min="0" value={Math.round(limit)} onChange={e=>setBudget({...budget,[cat]:Math.max(0,+e.target.value)})}/></div></div>})}</div><div className="card budgetRules"><h2>{ar?'فحص الخطة':'Plan checks'}</h2><BudgetCheck ok={total<=profile.income} text={ar?'إجمالي الخطة لا يتجاوز الدخل':'Total plan stays within income'}/><BudgetCheck ok={(budget.Savings||0)>=profile.income*.1} text={ar?'الادخار 10٪ على الأقل':'At least 10% assigned to savings'}/><BudgetCheck ok={(budget.Emergency||0)>0} text={ar?'مساهمة شهرية للطوارئ':'Monthly emergency contribution'}/><BudgetCheck ok={(budget.Housing||0)<=profile.income*.35} text={ar?'السكن لا يتجاوز 35٪':'Housing remains below 35%'}/><div className="budgetRatio"><span>{ar?'نسبة التوزيع':'Allocation ratio'}</span><b>{profile.income?(total/profile.income*100).toFixed(0):0}%</b></div><button className="outline" onClick={()=>act(ar?'تحسين الميزانية':'Optimize budget')}>{ar?'حسّن الخطة مع AI':'Optimize with AI'} <Sparkles/></button></div></div></PageWrap>}
function BudgetCheck({ok,text}:{ok:boolean;text:string}){return <div className={`budgetCheck ${ok?'ok':'warn'}`}>{ok?<CheckCircle2/>:<AlertTriangle/>}<span>{text}</span></div>}

function AnalyticsPage({profile,ar}:{profile:Profile;ar:boolean}){const [ml,setMl]=useState<any>(null),[recommendations,setRecommendations]=useState<any[]>([]),[mlError,setMlError]=useState(''),[loading,setLoading]=useState(true);const refresh=async()=>{setLoading(true);setMlError('');try{await api('/recommendations/refresh',{method:'POST'});setRecommendations(await api('/recommendations'))}catch{}try{setMl(await api('/ml/insights'))}catch(e){setMlError(ar?'نماذج التعلم الآلي غير متاحة أو لم تُدرّب بعد. لا توجد ثقة أو توقعات مصطنعة.':'ML models are unavailable or not trained. No fabricated confidence or prediction is shown.')}finally{setLoading(false)}};useEffect(()=>{refresh()},[]);const demo=ml?.prediction?.dataset_classification==='synthetic-demo';return <PageWrap title={ar?'التحليلات الذكية':'Smart insights'} sub={ar?'توقعات تعلم آلي وتوصيات قابلة للتفسير من بيانات الخادم.':'ML projections and explainable recommendations from server data.'}>{demo&&<div className="card dataNeeded"><Info/><div><h2>{ar?'وضع نموذج تجريبي':'Synthetic demo model'}</h2><p>{ar?'هذه النتائج لتجربة التكامل فقط، ومدرّبة على بيانات صناعية وليست تحققًا واقعيًا أو توقعًا إنتاجيًا.':'These results exercise the integration only. The models were trained on synthetic data and are not real-world validation or production forecasts.'}</p></div></div>}{loading&&<div className="card dataNeeded"><ChartSpline/><p>{ar?'جارٍ تحليل البيانات…':'Analyzing authoritative data…'}</p></div>}{mlError&&<div className="card dataNeeded"><AlertTriangle/><div><h2>{ar?'التعلم الآلي غير متاح':'ML unavailable'}</h2><p>{mlError}</p></div><button className="outline" onClick={refresh}>{ar?'إعادة المحاولة':'Retry'}</button></div>}{ml&&<div className="insightMetrics"><div className="card"><span>{ar?'مصروفات الشهر القادم':'Next-month expenses'}</span><b>{fmt(Number(ml.prediction.predicted_expense),profile)}</b><small>{ar?'تنبؤ النموذج المدرب':'Trained model prediction'}</small></div><div className="card"><span>{ar?'النمط المالي':'Financial behavior'}</span><b>{ml.behavior.profile}</b><small>{ar?'المسافة عن مركز المجموعة وليست نسبة ثقة':'Centroid distance—not confidence'}: {ml.behavior.distance_to_centroid}</small></div><div className="card"><span>{ar?'حالة الشذوذ':'Anomaly status'}</span><b>{ml.anomaly.is_anomaly?(ar?'يحتاج مراجعة':'Review'):(ar?'طبيعي':'Normal')}</b><small>{ar?'درجة النموذج':'Model score'}: {ml.anomaly.anomaly_score}</small></div></div>}<div className="analyticsGrid"><div className="card recommendationPanel"><div className="cardHead"><div><h2>{ar?'التوصيات الشخصية':'Personalized recommendations'}</h2><p>{ar?'مرتبة ومخزنة مع السبب والتأثير التقديري':'Ranked and stored with reason and estimated impact'}</p></div></div>{recommendations.map(r=><div className="recommendation info" key={r.id}><span><Sparkles/></span><div><b>{r.title}</b><p>{r.explanation}</p><small>{ar?'السبب':'Reason'}: {r.reason}{r.estimated_impact!=null?` · ${fmt(Number(r.estimated_impact),profile)}`:''}</small></div></div>)}{!recommendations.length&&!loading&&<div className="miniEmpty"><ShieldCheck/><b>{ar?'لا توجد توصيات نشطة':'No active recommendations'}</b></div>}</div><div className="card anomalyPanel"><h2>{ar?'منهجية واضحة':'Transparent methodology'}</h2><p>{ar?'لا تعرض الشاشة مستوى ثقة إلا إذا كان النموذج ينتجه ويقيم معايرته. اكتشاف الشذوذ يعرض الدرجة وسياق الفئة، وليس تفسيرًا سببيًا.':'Confidence is not displayed unless produced and calibration-tested by the model. Anomaly results show a score and category context, not a causal explanation.'}</p></div></div></PageWrap>}

function Ratio({label,value,target,good=false}:{label:string;value:number;target:string;good?:boolean}){const healthy=good?value>=.2:value<=.35;return <div className="ratio"><span>{label}</span><div><i style={{width:Math.min(100,value*100)+'%',background:healthy?'#4cb8a7':'#d39c45'}}/></div><b>{(value*100).toFixed(1)}%</b><small>{target}</small></div>}
function translateInsight(x:string){const map:Record<string,string>={'Spending leaves little margin':'الإنفاق يترك هامشًا محدودًا','Healthy savings capacity':'قدرة ادخارية جيدة','Expenses may rise next month':'قد ترتفع المصروفات الشهر القادم','Emergency reserve gap':'فجوة في احتياطي الطوارئ','Debt needs a structured payoff plan':'الديون تحتاج خطة سداد منظمة','Your financial foundation is stable':'أساسك المالي مستقر'};return map[x]||x.replace('unusual transaction detected','عملية غير طبيعية تم اكتشافها').replace('unusual transactions detected','عمليات غير طبيعية تم اكتشافها')}

function GuidancePage({profile,ar,onAsk}:{profile:Profile;ar:boolean;onAsk:(q:string)=>void}){const [done,setDone]=useState<string[]>([]);useEffect(()=>{try{setDone(JSON.parse(localStorage.getItem('swa-guidance-done')||'[]'))}catch{}},[]);const toggle=(id:string)=>{const next=done.includes(id)?done.filter(x=>x!==id):[...done,id];setDone(next);localStorage.setItem('swa-guidance-done',JSON.stringify(next))};const emergencyTarget=profile.essentialExpenses*6,monthlySurplus=profile.income-profile.expenses;const phases=[{n:'30',title:ar?'ثبّت الأساس المالي':'Stabilize the foundation',items:ar?['سجّل كل العمليات لمدة شهر','راجع الاشتراكات والمصروفات المتكررة',`وجّه جزءًا من الفائض ${fmt(Math.max(0,monthlySurplus),profile)} للطوارئ`]:['Track every transaction for one month','Review subscriptions and recurring costs',`Direct part of the ${fmt(Math.max(0,monthlySurplus),profile)} surplus to reserves`]},{n:'60',title:ar?'قلّل المخاطر':'Reduce financial risk',items:ar?[`ابنِ احتياطيًا باتجاه ${fmt(emergencyTarget,profile)}`,'رتّب الديون حسب تكلفة الفائدة','ثبّت حدود الميزانية وأتمت الادخار']:[`Build reserves toward ${fmt(emergencyTarget,profile)}`,'Rank debts by effective interest cost','Lock budget limits and automate saving']},{n:'90',title:ar?'ابدأ النمو المنظم':'Start structured growth',items:ar?['اربط كل استثمار بهدف ومدة','ابدأ بتوزيع متنوع ومنخفض التكلفة','حدّد موعد مراجعة ربع سنوي']:[ 'Link each investment to a goal and horizon','Start with diversified, cost-aware allocation','Schedule a quarterly plan review']}];const modules=[['Emergency fund','صندوق الطوارئ','Liquidity before investment risk','السيولة قبل مخاطر الاستثمار'],['Debt strategy','استراتيجية الديون','Avalanche, snowball, and refinancing','المقارنة بين السداد الأعلى فائدة والأصغر أولًا وإعادة التمويل'],['Investment basics','أساسيات الاستثمار','Diversification, fees, risk, and horizon','التنويع والرسوم والمخاطر والمدة'],['Goal planning','تخطيط الأهداف','Targets, deadlines, inflation, and trade-offs','الأهداف والمواعيد والتضخم والمفاضلات'],['Fraud protection','الحماية من الاحتيال','Safe accounts, alerts, and verification','حماية الحسابات والتنبيهات والتحقق'],['Review routine','روتين المراجعة','A repeatable monthly financial review','مراجعة مالية شهرية قابلة للتكرار']];return <PageWrap title={ar?'مركز الإرشادات المالية':'Financial guidance center'} sub={ar?'خطة عملية وتعليم مالي مخصص دون وعود أو قرارات غامضة.':'A practical, personalized learning path without promises or hidden decisions.'}><div className="guidanceHero card"><div><span className="eyebrow"><BookOpen/>{ar?'خطة التنفيذ':'YOUR ACTION ROADMAP'}</span><h2>{ar?'من المعرفة إلى خطوات قابلة للتنفيذ':'Turn financial knowledge into consistent action'}</h2><p>{ar?'الخطة مبنية على وضعك الحالي وتُحدّث مع بياناتك. راجع الافتراضات قبل أي قرار.':'This roadmap reflects your current profile and evolves with your data. Review assumptions before acting.'}</p></div><button className="primary" onClick={()=>onAsk(ar?'راجع وضعي المالي وأنشئ لي خطة مفصلة لمدة 90 يومًا مع أولويات واضحة':'Review my financial situation and create a detailed prioritized 90-day plan')}><Sparkles/>{ar?'خصص الخطة مع AI':'Personalize with AI'}</button></div><div className="roadmap">{phases.map(p=><div className="card phase" key={p.n}><span className="phaseNo">{ar?'يوم':'DAY'} {p.n}</span><h2>{p.title}</h2>{p.items.map((x,i)=>{const id=p.n+'-'+i;return <button className={done.includes(id)?'done':''} onClick={()=>toggle(id)} key={id}><span>{done.includes(id)?<CheckCircle2/>:<i/>}</span>{x}</button>})}<small>{p.items.filter((_,i)=>done.includes(p.n+'-'+i)).length}/{p.items.length} {ar?'مكتمل':'complete'}</small></div>)}</div><div className="guidanceGrid"><div className="card learning"><div className="cardHead"><div><h2>{ar?'مكتبة الإرشادات':'Guidance library'}</h2><p>{ar?'موضوعات أساسية لاتخاذ قرارات أفضل':'Essential topics for better decisions'}</p></div></div><div className="moduleGrid">{modules.map(m=><button key={m[0]} onClick={()=>onAsk(ar?`اشرح لي ${m[1]} بناءً على وضعي المالي وبأمثلة واضحة`:`Teach me about ${m[0]} using my financial situation and clear examples`)}><span><BookOpen/></span><div><b>{ar?m[1]:m[0]}</b><small>{ar?m[3]:m[2]}</small></div><ChevronRight/></button>)}</div></div><div className="card safetyGuide"><h2>{ar?'قبل أي قرار استثماري':'Before any investment decision'}</h2>{(ar?['احتياطي الطوارئ كافٍ','الديون مرتفعة التكلفة تحت السيطرة','الهدف والمدة واضحان','أفهم احتمال خسارة رأس المال','الرسوم والسيولة والضرائب معروفة']:['Emergency reserve is adequate','Expensive debt is controlled','Goal and horizon are clear','I understand principal-loss risk','Fees, liquidity, and tax caveats are known']).map((x,i)=><div key={x}><span>{i<2&&profile.savings>=profile.expenses*3?<CheckCircle2/>:<Info/>}</span>{x}</div>)}<button className="outline" onClick={()=>onAsk(ar?'افحص جاهزيتي للاستثمار ووضح أي نقاط ناقصة':'Check my investment readiness and explain any gaps')}><ShieldCheck/>{ar?'افحص جاهزيتي':'Check readiness'}</button></div></div></PageWrap>}

function Portfolio({profile,ar}:{profile:Profile;ar:boolean}){const [portfolios,setPortfolios]=useState<any[]>([]),[risk,setRisk]=useState<any>(null),[error,setError]=useState('');const load=()=>api<any[]>('/portfolios').then(setPortfolios).catch(e=>setError(e.message));useEffect(()=>{load();api<any>('/risk-assessments/latest').then(setRisk).catch(()=>{})},[]);const assess=async()=>{const keys=['loss_reaction','return_preference','experience','horizon','liquidity','income_stability'];const answers:any={};for(const key of keys){const value=Number(prompt(`${key.replaceAll('_',' ')} (1–5)`,'3'));if(!Number.isInteger(value)||value<1||value>5)return alert(ar?'يجب أن تكون كل إجابة من 1 إلى 5':'Every answer must be an integer from 1 to 5');answers[key]=value}try{setRisk(await api('/risk-assessments',json('POST',{answers})))}catch(e){setError(e instanceof Error?e.message:'Risk assessment failed')}};const create=async()=>{const name=prompt(ar?'اسم المحفظة':'Portfolio name');if(!name)return;await api('/portfolios',json('POST',{name,currency:profile.currency}));load()};const add=async(id:string)=>{const symbol=prompt(ar?'رمز الأصل':'Asset symbol');if(!symbol)return;const asset_class=prompt(ar?'فئة الأصل':'Asset class')||'Other';const quantity=Number(prompt(ar?'الكمية':'Quantity'));const current_price=Number(prompt(ar?'السعر الحالي':'Current price'));const cost_basis=Number(prompt(ar?'إجمالي تكلفة الشراء':'Total cost basis'));if([quantity,current_price,cost_basis].some(x=>!Number.isFinite(x)||x<0))return;await api(`/portfolios/${id}/positions`,json('POST',{symbol,asset_class,quantity,current_price,cost_basis,currency:profile.currency}));load()};return <PageWrap title={ar?'محفظتك':'Your portfolio'} sub={ar?'حساب فعلي للقيمة والتوزيع والتركيز من المراكز المسجلة.':'Actual value, allocation, and concentration from recorded positions.'}><div className="strategy card"><div><span className="eyebrow"><WalletCards/> {ar?'بيانات المحفظة':'PORTFOLIO RECORDS'}</span><h2>{portfolios.length?`${portfolios.length} ${ar?'محفظة':'portfolios'}`:(ar?'ابدأ بتسجيل محفظتك':'Record your first portfolio')}</h2><p>{ar?'الأسعار تُدخل يدويًا ولا تمثل بيانات سوق حية.':'Prices are user-entered and are not represented as live market data.'}</p>{risk&&<small>{ar?'ملف المخاطر التعليمي':'Educational risk profile'}: <b>{risk.category}</b> · {Number(risk.score).toFixed(0)}/100</small>}</div><div className="formActions"><button className="outline" onClick={assess}><ShieldCheck/>{ar?'تقييم المخاطر':'Assess risk'}</button><button className="primary" onClick={create}><Plus/>{ar?'إضافة محفظة':'Add portfolio'}</button></div></div>{error&&<div className="card dataNeeded"><AlertTriangle/><p>{error}</p></div>}<div className="portfolioGrid">{portfolios.map(p=><div className="card holdings" key={p.id}><div className="cardHead"><div><h2>{p.name}</h2><p>{fmt(Number(p.value),profile)} · {p.positions.length} {ar?'مراكز':'positions'}</p></div><button className="outline" onClick={()=>add(p.id)}><Plus/>{ar?'إضافة مركز':'Add position'}</button></div>{p.positions.map((x:any)=><div className="holding" key={x.id}><i style={{background:'#3267e3'}}/><div><b>{x.symbol}</b><span>{x.asset_class}</span></div><div className="holdingBar"><i style={{width:`${Math.min(100,p.allocation[x.asset_class]||0)}%`,background:'#3267e3'}}/></div><strong>{fmt(Number(x.market_value),profile)}</strong><em>{(p.allocation[x.asset_class]||0).toFixed(1)}%</em></div>)}<p className="disclaimer"><Info/> {ar?'أكبر فئة':'Largest class'}: {Number(p.largest_asset_weight).toFixed(1)}% · {ar?'فئات فعالة':'Effective classes'}: {p.effective_asset_classes}</p></div>)}<div className="card riskCard"><h2>{ar?'مخاطر التركيز':'Concentration check'}</h2><p>{ar?'التنوع لا يضمن منع الخسائر، والبيانات تعتمد على الأسعار التي أدخلتها.':'Diversification does not prevent losses; calculations depend on your entered prices.'}</p>{portfolios.map(p=><Stress key={p.id} label={p.name} value={`${Number(p.largest_asset_weight).toFixed(1)}%`} pct={Number(p.largest_asset_weight)>50?(ar?'تركيز مرتفع':'High concentration'):(ar?'موزع':'Distributed')} good={Number(p.largest_asset_weight)<=50}/>)}</div></div></PageWrap>}

function Stat({label,value}:{label:string,value:string}){return <div><span>{label}</span><b>{value}</b></div>}
function Stress({label,value,pct,good}:{label:string,value:string,pct:string,good?:boolean}){return <div className="stress"><span>{label}</span><b>{value}</b><em className={good?'positive':'negative'}>{pct}</em></div>}
function Goals({profile,ar}:{profile:Profile;ar:boolean}){const [goals,setGoals]=useState<any[]>([]),[error,setError]=useState('');const load=()=>api<any[]>('/goals').then(setGoals).catch(e=>setError(e.message));useEffect(()=>{load()},[]);const add=async()=>{const name=prompt(ar?'اسم الهدف':'Goal name');if(!name)return;const target=Number(prompt(ar?'المبلغ المستهدف':'Target amount'));if(!(target>0))return;await api('/goals',json('POST',{name,target_amount:target,current_amount:0,currency:profile.currency,priority:2}));load()};const contribute=async(g:any)=>{const amount=Number(prompt(ar?'قيمة المساهمة':'Contribution amount'));if(!(amount>0))return;await api(`/goals/${g.id}/contributions`,json('POST',{amount,contributed_on:new Date().toISOString().slice(0,10)}));load()};const remove=async(g:any)=>{if(confirm(ar?'حذف الهدف؟':'Delete goal?')){await api(`/goals/${g.id}`,{method:'DELETE'});load()}};const overall=goals.length?goals.reduce((n,g)=>n+Number(g.progress_percent),0)/goals.length:0;return <PageWrap title={ar?'الأهداف':'Goals'} sub={ar?'حوّل طموحاتك إلى خطط واضحة قابلة للقياس.':'Turn your ambitions into clear, measurable plans.'}><div className="goalHero card"><div><span className="eyebrow"><Target/> {ar?'توقع الأهداف':'GOAL FORECAST'}</span><h2>{ar?`${goals.length} أهداف نشطة`:`${goals.length} active goals`}</h2><p>{ar?'تُحسب المساهمات والتقدم من بياناتك المحفوظة.':'Contributions and progress are calculated from your saved records.'}</p><button className="primary" onClick={add}><Plus/>{ar?'إضافة هدف':'Add a goal'}</button></div><div className="bigRing"><div><b>{overall.toFixed(0)}%</b><span>{ar?'التقدم الإجمالي':'Overall progress'}</span></div></div></div>{error&&<div className="card dataNeeded"><AlertTriangle/><p>{error}</p></div>}<div className="goalCards">{goals.map((g:any)=><div className="card goalBox" key={g.id}><span className="goalTag">{g.deadline|| (ar?'بدون موعد':'No deadline')}</span><h2>{g.name}</h2><p><b>{fmt(Number(g.current_amount),profile)}</b> {ar?'من':'of'} {fmt(Number(g.target_amount),profile)}</p><div className="progress big"><i style={{width:Math.min(100,Number(g.progress_percent))+'%',background:'#3267e3'}}/></div><div><span>{Number(g.progress_percent).toFixed(1)}% {ar?'ممول':'funded'}</span><b>{g.required_monthly_saving?`${fmt(Number(g.required_monthly_saving),profile)}/${ar?'شهر':'mo'}`:(ar?'مكتمل':'Complete')}</b></div><div className="formActions"><button className="outline" onClick={()=>contribute(g)}>{ar?'إضافة مساهمة':'Contribute'}</button><button className="deleteBtn" onClick={()=>remove(g)}><Trash2/></button></div></div>)}{goals.length===0&&<div className="card emptyState"><Target/><h3>{ar?'لا توجد أهداف بعد':'No goals yet'}</h3><button className="primary" onClick={add}>{ar?'أضف هدفك الأول':'Add your first goal'}</button></div>}</div></PageWrap>}


type ProjectIdea={name:string;type:string;capital:number;monthly:number;risk:string;time:string;score:number;icon:any;color:string;why:string;steps:string[]};
function getProjects(p:Profile):ProjectIdea[]{
 const c=p.capital;const ideas:ProjectIdea[]=[
 {name:'Niche online store',type:'Digital commerce',capital:Math.min(c*.22,12000),monthly:Math.min(c*.025,1600),risk:'Medium',time:'8–12 hrs/week',score:p.horizon>=7?91:84,icon:Store,color:'#3267e3',why:'Can be validated with a small inventory and scaled from cash flow.',steps:['Choose one underserved niche','Validate with 20 customer interviews','Launch a 30-day paid pilot']},
 {name:'B2B micro-SaaS',type:'Digital product',capital:Math.min(c*.18,18000),monthly:Math.min(c*.035,2400),risk:'High',time:'12–18 hrs/week',score:p.risk==='Conservative'?70:89,icon:Rocket,color:'#7e68c7',why:'Recurring revenue potential and low marginal costs, but requires product execution.',steps:['Find a repetitive business workflow','Pre-sell to 5 businesses','Build only the paid core workflow']},
 {name:'Managed service studio',type:'Service business',capital:Math.min(c*.1,7000),monthly:Math.min(c*.03,2000),risk:'Medium',time:'10–15 hrs/week',score:93,icon:Briefcase,color:'#4cb8a7',why:'Low fixed costs and fast validation using skills before hiring.',steps:['Package one measurable outcome','Sign 3 pilot clients','Document delivery and delegate']},
 {name:'Fractional rental property',type:'Real estate',capital:Math.min(c*.35,35000),monthly:Math.min(c*.012,1100),risk:'Medium',time:'2–4 hrs/week',score:c>25000?82:66,icon:Building2,color:'#d39c45',why:'Potential income and inflation sensitivity, with liquidity and concentration trade-offs.',steps:['Check local legal structure','Model vacancy, fees and financing','Stress-test a 20% price decline']},
 ];return ideas.sort((a,b)=>b.score-a.score)
}
function Projects({profile,onAsk}:{profile:Profile;onAsk:(q:string)=>void}){const [type,setType]=useState('All');const [selected,setSelected]=useState<ProjectIdea|null>(null);const ideas=getProjects(profile).filter(x=>type==='All'||x.type.includes(type));const reserveTarget=profile.essentialExpenses>0?profile.essentialExpenses*6:null;return <PageWrap title="Project idea library" sub={`Illustrative ideas to research in ${profile.country}; they are not ranked or validated recommendations.`} action="Build a project plan"><div className="projectHero card"><div><span className="eyebrow"><BrainCircuit/> EDUCATIONAL IDEA LIBRARY</span><h2>Don’t invest all your capital in one idea</h2><p>{reserveTarget!=null?`A six-month reserve target based on recorded essential expenses is ${fmt(reserveTarget,profile)}. `:'A reserve target is unavailable until essential expenses are classified. '}Validate demand in small stages before committing money.</p></div><div className="capitalBadge"><span>Recorded available capital</span><b>{fmt(profile.capital,profile)}</b><small>{profile.risk} educational risk profile</small></div></div><div className="projectToolbar"><div>{['All','Digital','Service','Real estate'].map(x=><button key={x} className={type===x?'active':''} onClick={()=>setType(x)}>{x}</button>)}</div><span><Info/> Income figures are editable illustrative scenarios, not forecasts</span></div><div className="projectGrid">{ideas.map(x=><div className="card projectCard" key={x.name}><div className="projectTop"><span className="projectIcon" style={{color:x.color,background:x.color+'16'}}><x.icon/></span><span className="match">UNVALIDATED IDEA</span></div><small>{x.type}</small><h2>{x.name}</h2><p>{x.why}</p><div className="projectStats"><div><span>Test capital</span><b>{fmt(x.capital,profile)}</b></div><div><span>Scenario income</span><b>{fmt(x.monthly,profile)}/mo</b></div></div><div className="projectMeta"><span><i className={`dot ${x.risk.toLowerCase()}`}/>{x.risk} risk</span><span>{x.time}</span></div><button className="outline" onClick={()=>setSelected(x)}>View validation plan <ChevronRight/></button></div>)}</div>{selected&&<div className="projectDrawer"><div className="projectDetail card"><button className="detailClose" onClick={()=>setSelected(null)}><X/></button><span className="projectIcon" style={{color:selected.color,background:selected.color+'16'}}><selected.icon/></span><span className="eyebrow">PERSONALIZED PROJECT BLUEPRINT</span><h1>{selected.name}</h1><p>{selected.why}</p><h3>90-day validation plan</h3>{selected.steps.map((s,i)=><div className="projectStep" key={s}><i>{i+1}</i><div><b>{s}</b><span>{i===0?'Weeks 1–2 · Research before spending':i===1?'Weeks 3–6 · Collect real demand signals':'Weeks 7–12 · Measure, improve, then scale'}</span></div></div>)}<div className="riskNote"><Info/><div><b>Key assumption</b><span>The income figure is an illustrative scenario before tax and may be zero or negative. Validate unit economics and local regulations.</span></div></div><button className="primary" onClick={()=>{onAsk(`Create a detailed 90-day plan for ${selected.name} using my financial profile`);setSelected(null)}}><Sparkles/>Discuss this project with AI</button></div></div>}</PageWrap>}

function Simulator({profile}:{profile:Profile}){const [amount,setAmount]=useState(10000),[monthly,setMonthly]=useState(500),[years,setYears]=useState(10),[shock,setShock]=useState(0),[result,setResult]=useState<any>(null),[loading,setLoading]=useState(false),[error,setError]=useState('');const run=async()=>{setLoading(true);setError('');try{setResult(await api('/scenarios/monte-carlo',json('POST',{initial_capital:amount*(1+shock/100),monthly_contribution:monthly,horizon_years:years,expected_return:.075,volatility:.14,inflation:.03,simulations:10000,goal_amount:amount+monthly*years*12,seed:42})))}catch(e){setError(e instanceof Error?e.message:'Simulation failed')}finally{setLoading(false)}};useEffect(()=>{run()},[]);const deposits=amount+monthly*years*12;return <PageWrap title="Scenario simulator" sub="Reproducible Monte Carlo ranges—not promised outcomes."><div className="simGrid"><div className="card controls"><span className="eyebrow"><Orbit/> WHAT HAPPENS IF…</span><label>Initial investment <b>{fmt(amount,profile)}</b></label><input type="range" min="0" max="100000" step="1000" value={amount} onChange={e=>setAmount(+e.target.value)}/><label>Monthly contribution <b>{fmt(monthly,profile)}</b></label><input type="range" min="0" max="5000" step="100" value={monthly} onChange={e=>setMonthly(+e.target.value)}/><label>Time horizon <b>{years} years</b></label><input type="range" min="1" max="30" value={years} onChange={e=>setYears(+e.target.value)}/><h3>Immediate market event</h3><div className="shockBtns">{[[0,'Base case'],[-20,'Market −20%'],[-35,'Severe −35%']].map(x=><button className={shock===x[0]?'active':''} onClick={()=>setShock(+x[0])} key={x[1]}>{x[1]}</button>)}</div><button className="primary" disabled={loading} onClick={run}><Orbit/>{loading?'Simulating…':'Run 10,000 paths'}</button></div><div className="card outcome"><div className="cardHead"><div><h2>Projected real-value range</h2><p>7.5% return, 14% volatility, 3% inflation assumptions</p></div><span className="scenarioTag">MONTE CARLO</span></div>{error?<div className="dataNeeded"><AlertTriangle/><p>{error}</p></div>:result?<><div className="outcomeValue"><span>Median (P50) in {years} years</span><b>{fmt(result.p50,profile)}</b><em>{result.probability_of_goal}% probability of reaching the contribution benchmark</em></div><div className="outcomeStats"><Stat label="Downside P10" value={fmt(result.p10,profile)}/><Stat label="Median P50" value={fmt(result.p50,profile)}/><Stat label="Upside P90" value={fmt(result.p90,profile)}/></div></>:<div className="loading"><span>Run the simulation</span></div>}<p className="disclaimer"><Info/> Educational projection using independent normally distributed monthly returns. Taxes, fees and fat-tail events are excluded. Results are not guarantees.</p></div></div></PageWrap>}

function MiniProjection({years,shock}:{years:number,shock:number}){return <div className="miniProjection"><svg viewBox="0 0 600 180" preserveAspectRatio="none"><defs><linearGradient id="proj" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#3267e3" stopOpacity=".2"/><stop offset="1" stopColor="#3267e3" stopOpacity="0"/></linearGradient></defs><path d={shock?'M0 165 C80 155 120 140 160 130 L180 170 C250 145 310 115 370 90 S500 44 600 12 L600 180 L0 180Z':'M0 165 C80 155 120 140 180 130 S280 105 360 82 S470 44 600 12 L600 180 L0 180Z'} fill="url(#proj)"/><path d={shock?'M0 165 C80 155 120 140 160 130 L180 170 C250 145 310 115 370 90 S500 44 600 12':'M0 165 C80 155 120 140 180 130 S280 105 360 82 S470 44 600 12'} fill="none" stroke="#3267e3" strokeWidth="3"/></svg><div><span>Today</span><span>Year {Math.round(years/2)}</span><span>Year {years}</span></div></div>}
function Calculators(){
 const tabs=['Compound growth','Retirement','FIRE','Mortgage','Loan','Passive income'];const [active,setActive]=useState(tabs[0]);const [principal,setPrincipal]=useState(25000),[rate,setRate]=useState(7),[years,setYears]=useState(15),[monthly,setMonthly]=useState(750);const [age,setAge]=useState(32),[retireAge,setRetireAge]=useState(60),[expenses,setExpenses]=useState(2500),[price,setPrice]=useState(250000),[down,setDown]=useState(50000),[loanRate,setLoanRate]=useState(6),[loanYears,setLoanYears]=useState(20),[loanAmount,setLoanAmount]=useState(50000),[targetIncome,setTargetIncome]=useState(2000),[yieldRate,setYieldRate]=useState(5);
 const compound=(start:number,contrib:number,r:number,y:number)=>{const mr=r/100/12,n=y*12;return mr?start*Math.pow(1+mr,n)+contrib*((Math.pow(1+mr,n)-1)/mr):start+contrib*n};
 const fv=compound(principal,monthly,rate,years);const retireYears=Math.max(1,retireAge-age),retireValue=compound(principal,monthly,rate,retireYears),retireIncome=retireValue*.04/12;const fireTarget=expenses*12*25;let fireYears=0,fireBalance=principal;while(fireBalance<fireTarget&&fireYears<60){fireBalance=compound(fireBalance,monthly,rate,1);fireYears++}const mortgagePrincipal=Math.max(0,price-down);const mortgageMonthlyRate=loanRate/100/12;const mortgageN=loanYears*12;const mortgagePayment=mortgageMonthlyRate?mortgagePrincipal*mortgageMonthlyRate*Math.pow(1+mortgageMonthlyRate,mortgageN)/(Math.pow(1+mortgageMonthlyRate,mortgageN)-1):mortgagePrincipal/mortgageN;const loanMonthlyRate=loanRate/100/12;const loanN=loanYears*12;const loanPayment=loanMonthlyRate?loanAmount*loanMonthlyRate*Math.pow(1+loanMonthlyRate,loanN)/(Math.pow(1+loanMonthlyRate,loanN)-1):loanAmount/loanN;const passiveCapital=targetIncome*12/(yieldRate/100);
 const Slider=({label,value,set,min,max,step=1,suffix='',prefix=''}:{label:string,value:number,set:(n:number)=>void,min:number,max:number,step?:number,suffix?:string,prefix?:string})=><div className="calcInput"><label>{label}<b>{prefix}{value.toLocaleString()}{suffix}</b></label><input type="range" value={value} min={min} max={max} step={step} onChange={e=>set(+e.target.value)}/></div>;
 let controls:React.ReactNode,resultTitle='',result=0,resultSub='',stats:[string,string][]=[];
 if(active==='Compound growth'){controls=<><Slider label="Starting amount" value={principal} set={setPrincipal} min={0} max={200000} step={1000} prefix="$"/><Slider label="Monthly contribution" value={monthly} set={setMonthly} min={0} max={5000} step={50} prefix="$"/><Slider label="Annual return" value={rate} set={setRate} min={1} max={15} step={.5} suffix="%"/><Slider label="Time horizon" value={years} set={setYears} min={1} max={40} suffix=" years"/></>;resultTitle='Projected portfolio value';result=fv;resultSub=`after ${years} years`;stats=[['Total contributions',money(principal+monthly*years*12)],['Estimated growth',money(fv-principal-monthly*years*12)]]}
 else if(active==='Retirement'){controls=<><Slider label="Current age" value={age} set={setAge} min={18} max={70}/><Slider label="Retirement age" value={retireAge} set={setRetireAge} min={age+1} max={80}/><Slider label="Current invested savings" value={principal} set={setPrincipal} min={0} max={500000} step={5000} prefix="$"/><Slider label="Monthly contribution" value={monthly} set={setMonthly} min={0} max={8000} step={100} prefix="$"/><Slider label="Annual return" value={rate} set={setRate} min={1} max={12} step={.5} suffix="%"/></>;resultTitle='Portfolio at retirement';result=retireValue;resultSub=`at age ${retireAge}`;stats=[['Years to retirement',String(retireYears)],['Illustrative monthly income',money(retireIncome)]]}
 else if(active==='FIRE'){controls=<><Slider label="Monthly expenses" value={expenses} set={setExpenses} min={500} max={15000} step={100} prefix="$"/><Slider label="Current investments" value={principal} set={setPrincipal} min={0} max={1000000} step={5000} prefix="$"/><Slider label="Monthly contribution" value={monthly} set={setMonthly} min={0} max={10000} step={100} prefix="$"/><Slider label="Annual return" value={rate} set={setRate} min={1} max={12} step={.5} suffix="%"/></>;resultTitle='Financial independence target';result=fireTarget;resultSub='using an illustrative 4% rule';stats=[['Estimated time',fireYears>=60?'60+ years':`${fireYears} years`],['Current progress',`${Math.min(100,principal/fireTarget*100).toFixed(1)}%`]]}
 else if(active==='Mortgage'){controls=<><Slider label="Property price" value={price} set={setPrice} min={25000} max={1500000} step={5000} prefix="$"/><Slider label="Down payment" value={down} set={setDown} min={0} max={Math.max(0,price*.9)} step={5000} prefix="$"/><Slider label="Mortgage rate" value={loanRate} set={setLoanRate} min={1} max={18} step={.25} suffix="%"/><Slider label="Loan term" value={loanYears} set={setLoanYears} min={1} max={35} suffix=" years"/></>;resultTitle='Estimated monthly payment';result=mortgagePayment;resultSub='principal and interest only';stats=[['Loan amount',money(mortgagePrincipal)],['Total interest',money(mortgagePayment*mortgageN-mortgagePrincipal)]]}
 else if(active==='Loan'){controls=<><Slider label="Loan amount" value={loanAmount} set={setLoanAmount} min={1000} max={500000} step={1000} prefix="$"/><Slider label="Interest rate" value={loanRate} set={setLoanRate} min={0} max={30} step={.25} suffix="%"/><Slider label="Loan term" value={loanYears} set={setLoanYears} min={1} max={15} suffix=" years"/></>;resultTitle='Estimated monthly payment';result=loanPayment;resultSub=`for ${loanYears} years`;stats=[['Total repayment',money(loanPayment*loanN)],['Total interest',money(loanPayment*loanN-loanAmount)]]}
 else{controls=<><Slider label="Target monthly income" value={targetIncome} set={setTargetIncome} min={100} max={20000} step={100} prefix="$"/><Slider label="Expected income yield" value={yieldRate} set={setYieldRate} min={1} max={15} step={.25} suffix="%"/><Slider label="Current investable capital" value={principal} set={setPrincipal} min={0} max={1000000} step={5000} prefix="$"/></>;resultTitle='Capital potentially required';result=passiveCapital;resultSub=`for ${money(targetIncome)} per month`;stats=[['Annual income target',money(targetIncome*12)],['Funding gap',money(Math.max(0,passiveCapital-principal))]]}
 return <PageWrap title="Financial calculators" sub="Clear numbers for your biggest money decisions."><div className="calcTabs">{tabs.map(x=><button key={x} className={active===x?'active':''} onClick={()=>setActive(x)}>{x}</button>)}</div><div className="calcGrid"><div className="card controls"><h2>{active}</h2><p>Adjust the assumptions to see results instantly.</p>{controls}</div><div className="card calcResult"><span>{resultTitle}</span><b>{money(result)}</b><p>{resultSub}</p><div className="resultSplit">{stats.map(x=><Stat key={x[0]} label={x[0]} value={x[1]}/>)}</div><MiniProjection years={active==='Retirement'?retireYears:active==='Mortgage'||active==='Loan'?loanYears:active==='FIRE'?Math.min(fireYears,40):years} shock={0}/><button className="primary" onClick={()=>downloadFile(`${active.replaceAll(' ','-').toLowerCase()}-calculation.json`,JSON.stringify({calculator:active,result:Math.round(result),stats,generatedAt:new Date().toISOString()},null,2),'application/json')}><Download/> Save calculation</button><p className="disclaimer"><Info/> Illustrative estimate only. Rates, taxes, fees and actual outcomes may differ.</p></div></div></PageWrap>
}
type ReportKind='health'|'wealth'|'spending'|'risk'|'retirement'|'action';
const reportInfo:Record<ReportKind,{en:string;ar:string;descEn:string;descAr:string}>={
 health:{en:'Financial Health Report',ar:'تقرير الصحة المالية',descEn:'Cash flow, reserves, debt ratios, and your overall financial foundation.',descAr:'التدفق النقدي والاحتياطي ونسب الديون والأساس المالي الكامل.'},
 wealth:{en:'Wealth Analysis',ar:'تحليل الثروة',descEn:'Net worth, available capital, growth scenarios, and diversification priorities.',descAr:'صافي الثروة ورأس المال وسيناريوهات النمو وأولويات التنويع.'},
 spending:{en:'Spending & Budget Review',ar:'تقرير المصروفات والميزانية',descEn:'Category spending, budget limits, unusual transactions, and savings opportunities.',descAr:'تصنيفات الإنفاق وحدود الميزانية والعمليات غير الطبيعية وفرص الادخار.'},
 risk:{en:'Risk Assessment',ar:'تقييم المخاطر',descEn:'Risk capacity, debt exposure, liquidity, and stress-test considerations.',descAr:'القدرة على تحمل المخاطر والتعرض للديون والسيولة واختبارات الضغط.'},
 retirement:{en:'Retirement Readiness',ar:'الاستعداد للتقاعد',descEn:'Illustrative retirement target, current funding, monthly gap, and assumptions.',descAr:'هدف تقاعد تقديري والتمويل الحالي والفجوة الشهرية والافتراضات.'},
 action:{en:'Personal Action Plan',ar:'خطة العمل الشخصية',descEn:'Prioritized next steps for the next 30, 60, and 90 days.',descAr:'خطوات عملية مرتبة للأيام الثلاثين والستين والتسعين القادمة.'}
};
const escapeHtml=(v:any)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]||c));
function reportDocument(kind:ReportKind,profile:Profile,data:any,ar:boolean){const info=reportInfo[kind],summary=data?.summary||{},title=ar?info.ar:info.en,currency=summary.currency||profile.currency,date=new Intl.DateTimeFormat(ar?'ar-EG':'en-US',{dateStyle:'long',timeStyle:'short'}).format(new Date(data?.generated_at||Date.now())),currencyFmt=(value:any)=>new Intl.NumberFormat(ar?'ar-EG':'en-US',{style:'currency',currency,maximumFractionDigits:2}).format(Number(value||0)),percent=(value:any)=>value==null?'—':`${Number(value).toFixed(1)}%`,months=(value:any)=>value==null?(ar?'غير متاح':'Unavailable'):`${Number(value).toFixed(1)} ${ar?'شهر':'months'}`;const rows=[[ar?'صافي الثروة':'Net worth',currencyFmt(summary.net_worth)],[ar?'إجمالي الأصول':'Total assets',currencyFmt(summary.total_assets)],[ar?'المدخرات السائلة':'Liquid savings',currencyFmt(summary.liquid_savings)],[ar?'الفائض الشهري':'Monthly surplus',currencyFmt(summary.monthly_surplus)],[ar?'نسبة الادخار':'Savings rate',percent(summary.savings_rate)],[ar?'تغطية الطوارئ':'Emergency coverage',months(summary.emergency_fund_months)],[ar?'خدمة الدين إلى الدخل':'Debt-service-to-income',percent(summary.debt_to_income_ratio)],[ar?'قيمة المحفظة':'Portfolio value',currencyFmt(summary.portfolio_value)]];const categoryRows=Object.entries(summary.expense_by_category||{}).sort((a:any,b:any)=>Number(b[1])-Number(a[1]));const recommendations=(data?.recommendations||[]).map((r:any)=>`<li><strong>${escapeHtml(r.title)}</strong><span>${escapeHtml(r.explanation)}</span><small>${ar?'الأولوية':'Priority'} ${r.priority} · ${escapeHtml(r.reason)}</small></li>`).join('');const assumptions=(data?.assumptions||[]).map((x:string)=>`<li>${escapeHtml(x)}</li>`).join('');return `<!doctype html><html lang="${ar?'ar':'en'}" dir="${ar?'rtl':'ltr'}"><head><meta charset="utf-8"><title>${escapeHtml(title)}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:Arial,"Segoe UI",sans-serif;color:#14213d;margin:0;background:#fff;font-size:12px;line-height:1.6}.page{max-width:820px;margin:auto}.brand{display:flex;justify-content:space-between;align-items:center;padding-bottom:18px;border-bottom:3px solid #3267e3}.brand h1{font-size:23px;margin:0}.brand p,.meta{margin:3px 0;color:#718096}.badge{background:#edf3ff;color:#3267e3;padding:7px 11px;border-radius:20px;font-weight:700;font-size:10px}.hero{padding:24px 0}.hero h2{font-size:26px;margin:0 0 6px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.metric{border:1px solid #e3e9f2;border-radius:10px;padding:12px}.metric span,.metric b{display:block}.metric span{color:#718096;font-size:9px}.metric b{font-size:14px;margin-top:4px}section{margin-top:22px}section h2{font-size:16px;border-bottom:1px solid #e3e9f2;padding-bottom:7px}table{width:100%;border-collapse:collapse}td{padding:8px;border-bottom:1px solid #e3e9f2}td:last-child{text-align:${ar?'left':'right'};font-weight:700}.recommendations{padding:0;list-style:none}.recommendations li{border:1px solid #e3e9f2;border-radius:8px;padding:11px;margin:7px 0}.recommendations strong,.recommendations span,.recommendations small{display:block}.recommendations span{color:#5e6c84}.recommendations small{color:#718096;margin-top:3px}.notice{margin-top:24px;padding:12px;background:#fff8e8;color:#735b22;border-radius:8px;font-size:10px}.method{background:#f6f8fc;border-radius:8px;padding:12px}.footer{margin-top:28px;padding-top:10px;border-top:1px solid #e3e9f2;color:#718096;font-size:9px;display:flex;justify-content:space-between}@media print{.page{max-width:none}}</style></head><body><div class="page"><div class="brand"><div><h1>Smart Wealth Advisor</h1><p>${ar?'تخطيط مالي واضح قائم على البيانات':'Transparent, data-based financial planning'}</p></div><span class="badge">${ar?'تقرير مسجل':'RECORDED SNAPSHOT'}</span></div><div class="hero"><h2>${escapeHtml(title)}</h2><p>${escapeHtml(ar?info.descAr:info.descEn)}</p><div class="meta">${ar?'أُعد لـ':'Prepared for'} ${escapeHtml(profile.name)} · ${escapeHtml(date)} · ${ar?'البيانات حتى':'Data as of'} ${escapeHtml(String(data?.data_as_of||'—'))}</div></div><div class="metrics">${rows.map(r=>`<div class="metric"><span>${escapeHtml(r[0])}</span><b>${escapeHtml(r[1])}</b></div>`).join('')}</div><section><h2>${ar?'الإنفاق حسب التصنيف الموحد':'Spending by normalized category'}</h2>${categoryRows.length?`<table>${categoryRows.map(([key,value]:any)=>`<tr><td>${escapeHtml(ar?(categoryAr[key[0].toUpperCase()+key.slice(1)]||key):key)}</td><td>${escapeHtml(currencyFmt(value))}</td></tr>`).join('')}</table>`:`<p>${ar?'لا توجد مصروفات مسجلة للفترة.':'No recorded expenses for this period.'}</p>`}</section><section><h2>${ar?'التوصيات ذات الأولوية':'Priority recommendations'}</h2><ul class="recommendations">${recommendations||`<li>${ar?'لا توجد توصيات نشطة في هذه اللقطة.':'No active recommendations in this snapshot.'}</li>`}</ul></section><section class="method"><h2>${ar?'المنهجية والافتراضات':'Methodology and assumptions'}</h2><p>${escapeHtml(String(summary.methodology_version||'summary-v2'))}</p><ul>${assumptions}</ul></section><div class="notice">${ar?'هذا التقرير يعرض حقائق مسجلة ومقاييس محسوبة بوضوح. أي محاكاة أو توصية تعليمية وليست ضمانًا أو نصيحة ضريبية أو قانونية. استخدم طباعة المتصفح للحفظ بصيغة PDF.':'This report separates recorded facts from calculated metrics. Simulations and recommendations are educational, not guarantees or tax/legal advice. Use browser Print to save as PDF.'}</div><div class="footer"><span>Smart Wealth Advisor</span><span>${escapeHtml(title)}</span></div></div></body></html>`}

function Reports({profile,ar}:{profile:Profile;ar:boolean}){const [selected,setSelected]=useState<ReportKind|null>(null),[selectedData,setSelectedData]=useState<any>(null),[history,setHistory]=useState<any[]>([]),[error,setError]=useState(''),[loading,setLoading]=useState(false);const loadHistory=()=>api<any[]>('/reports').then(x=>setHistory(x.map(r=>({...r,createdAt:r.created_at,data:r.snapshot}))));useEffect(()=>{loadHistory().catch(e=>setError(e.message))},[]);const generate=async(kind:ReportKind)=>{setLoading(true);setError('');try{const r=await api<any>('/reports',json('POST',{kind,locale:ar?'ar':'en'}));setSelectedData(r.data);await loadHistory();setSelected(kind)}catch(e){setError(e instanceof Error?e.message:'Report unavailable')}finally{setLoading(false)}};const html=(kind:ReportKind)=>reportDocument(kind,profile,selectedData,ar);const printReport=(kind:ReportKind)=>{const w=window.open('','_blank');if(!w){downloadFile(`${kind}-report.html`,html(kind),'text/html');return}w.document.open();w.document.write(html(kind));w.document.close();setTimeout(()=>w.print(),350)};const csv=(kind:ReportKind)=>{const summary=selectedData?.summary||{};const rows=[['Metric','Value'],['Data as of',selectedData?.data_as_of||''],['Net worth',summary.net_worth],['Total assets',summary.total_assets],['Liquid savings',summary.liquid_savings],['Monthly income',summary.total_income],['Monthly expenses',summary.total_expenses],['Essential expenses',summary.essential_expenses],['Monthly surplus',summary.monthly_surplus],['Savings rate',summary.savings_rate],['Debt service to income',summary.debt_to_income_ratio],['Portfolio value',summary.portfolio_value],['Methodology',summary.methodology_version]];downloadFile(`${kind}-data.csv`,rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv')};return <><section className="welcome pageTitle"><div><h1>{ar?'التقارير الاحترافية':'Professional reports'}</h1><p>{ar?'تقارير ثنائية اللغة مبنية على بياناتك الحالية، جاهزة للطباعة والتصدير.':'Bilingual reports built from your current data, ready to print and export.'}</p></div><button className="primary" onClick={()=>generate('health')}><Sparkles/>{ar?'إنشاء تقرير الآن':'Generate report'}</button></section>{error&&<div className="card dataNeeded"><AlertTriangle/><p>{error}</p><button className="outline" onClick={()=>loadHistory().catch(e=>setError(e.message))}>{ar?'إعادة المحاولة':'Retry'}</button></div>}{loading&&<div className="card dataNeeded"><FileText/><p>{ar?'جارٍ إنشاء لقطة التقرير…':'Generating authoritative report snapshot…'}</p></div>}<div className="reportStatus card"><div><span className="reportStatusIcon"><FileText/></span><div><span className="eyebrow">{ar?'مركز التقارير الذكية':'SMART REPORT CENTER'}</span><h2>{ar?'بياناتك تتحول إلى قرارات واضحة':'Turn your financial data into clear decisions'}</h2><p>{ar?'كل تقرير يعرض تاريخ البيانات والافتراضات والمخاطر والخطوات العملية.':'Every report includes data dates, assumptions, risks, and actionable next steps.'}</p></div></div><div className="reportQuality"><div><span>{ar?'مصدر البيانات':'Data source'}</span><b>{ar?'الخادم الموثوق':'Authoritative backend'}</b></div><div><span>{ar?'العمليات في آخر لقطة':'Transactions in latest snapshot'}</span><b>{selectedData?.summary?.transaction_count??history[0]?.data?.summary?.transaction_count??'—'}</b></div><div><span>{ar?'آخر إنشاء':'Last generated'}</span><b>{history.length?new Intl.DateTimeFormat(ar?'ar-EG':'en-US',{dateStyle:'medium'}).format(new Date(history[0].createdAt)):(ar?'لا يوجد':'None')}</b></div></div></div><div className="professionalReportGrid">{(Object.keys(reportInfo) as ReportKind[]).map((kind,i)=>{const info=reportInfo[kind];return <div className="card proReport" key={kind}><div className="proReportTop"><span className={`reportIcon tone${i}`}><FileText/></span><span className="reportFormat">PDF · HTML · CSV</span></div><h2>{ar?info.ar:info.en}</h2><p>{ar?info.descAr:info.descEn}</p><div className="reportFeatures"><span><CheckCircle2/>{ar?'بيانات حية':'Live data'}</span><span><ShieldCheck/>{ar?'افتراضات واضحة':'Clear assumptions'}</span></div><div className="reportActions"><button className="outline" onClick={()=>generate(kind)}>{ar?'معاينة':'Preview'}</button><button className="primary" onClick={()=>generate(kind)}><Sparkles/>{ar?'إنشاء':'Generate'}</button></div></div>})}</div>{history.length>0&&<div className="card reportHistory"><div className="cardHead"><div><h2>{ar?'سجل التقارير':'Report history'}</h2><p>{ar?'آخر اللقطات المحفوظة في قاعدة البيانات':'Recent snapshots stored in the database'}</p></div><button className="outline" onClick={async()=>{await api('/reports',{method:'DELETE'});setHistory([])}}>{ar?'مسح السجل':'Clear history'}</button></div>{history.slice(0,5).map(x=><div className="historyRow" key={x.id}><FileText/><div><b>{ar?reportInfo[x.kind as ReportKind].ar:reportInfo[x.kind as ReportKind].en}</b><span>{new Intl.DateTimeFormat(ar?'ar-EG':'en-US',{dateStyle:'medium',timeStyle:'short'}).format(new Date(x.createdAt))}</span></div><button onClick={()=>{setSelectedData(x.data);setSelected(x.kind)}}>{ar?'فتح':'Open'}<ChevronRight/></button></div>)}</div>}{selected&&<div className="reportPreviewOverlay" onClick={()=>setSelected(null)}><div className="reportPreviewPanel" onClick={e=>e.stopPropagation()}><div className="previewToolbar"><div><span>{ar?'معاينة التقرير':'REPORT PREVIEW'}</span><b>{ar?reportInfo[selected].ar:reportInfo[selected].en}</b></div><div><button onClick={()=>csv(selected)}>CSV</button><button onClick={()=>downloadFile(`${selected}-report.html`,html(selected),'text/html')}><Download/>{ar?'تنزيل':'Download'}</button><button className="primary" onClick={()=>printReport(selected)}>{ar?'طباعة / PDF':'Print / PDF'}</button><button className="iconBtn" onClick={()=>setSelected(null)}><X/></button></div></div><iframe title="Report preview" srcDoc={html(selected)}/></div></div>}</>}
function PageWrap({title,sub,action,children}:{title:string,sub:string,action?:string,children:React.ReactNode}){return <><section className="welcome pageTitle"><div><h1>{title}</h1><p>{sub}</p></div>{action&&<button className="primary" onClick={()=>act(action)}><Plus/>{action}</button>}</section>{children}</>}

function advisorReply(q:string,p:Profile){
 const x=q.toLowerCase();const surplus=p.income-p.expenses;const rate=p.income?surplus/p.income*100:0;const emergency=p.expenses*6;const investable=Math.max(0,p.capital-emergency);const lines:string[]=[];
 if(/invest|استثم|10000|10,000/.test(x)){lines.push(`Based on your ${p.risk.toLowerCase()} profile and ${p.horizon}-year horizon, protect your emergency reserve first.`);lines.push(`Keep about ${fmt(emergency,p)} liquid. Of your current capital, approximately ${fmt(investable,p)} may be available for long-term goals.`);lines.push(p.risk==='Conservative'?'An educational starting mix could emphasize 55% high-quality bonds, 25% diversified equities, 15% cash and 5% gold.':p.risk==='Aggressive'?'An educational starting mix could be 75% diversified global equities, 10% bonds, 5% cash, 5% REITs and 5% alternatives.':'An educational starting mix could be 55% diversified global equities, 25% high-quality bonds, 10% cash, 5% REITs and 5% gold.');}
 else if(/retire|fire|تقاعد|حرية/.test(x)){const annual=Math.max(0,p.expenses*12);const target=annual/0.04;lines.push(`A rough 4% rule starting target is ${fmt(target,p)}, before tax and without guarantees.`);lines.push(`At your current surplus of ${fmt(surplus,p)} per month, your savings rate is ${rate.toFixed(0)}%. Your full retirement analysis should also include inflation, pensions, fees, and changing expenses.`);}
 else if(/debt|دين|ديون/.test(x)){lines.push(p.debt>0?`You reported ${fmt(p.debt,p)} of debt. Prioritize minimum payments, then generally direct extra cash to the highest effective interest rate—especially if it is above the expected after-tax return of a diversified portfolio.`:'You reported no current debt. That improves your flexibility, but keep the figure updated before acting on this guidance.');}
 else if(/risk|stress|drop|مخاطر|هبوط/.test(x)){const loss=(p.capital+p.savings)*(.2);lines.push(`In a simplified 20% broad-market shock, the invested portion—not your protected cash reserve—could temporarily lose value. If everything were exposed, that would be about ${fmt(loss,p)}.`);lines.push(`Your ${p.risk} profile suggests using diversification, a ${fmt(emergency,p)} liquidity reserve, and annual or band-based rebalancing rather than reacting emotionally.`);}
 else if(/save|budget|expense|ادخار|ميزانية|مصروف/.test(x)){lines.push(`Your estimated monthly surplus is ${fmt(surplus,p)} and your savings rate is ${rate.toFixed(1)}%.`);lines.push(rate<10?'First target: bring the savings rate toward 10% by reviewing recurring and discretionary spending.':rate<20?'You have a useful base. A gradual target of 20% could accelerate your goals without creating an unrealistic budget.':'Your savings rate is strong. Automate transfers after payday and assign the surplus across reserves and goals.');}
 else {lines.push(`I’m using your profile: age ${p.age}, ${p.risk.toLowerCase()} risk, ${p.horizon}-year horizon, and the goal “${p.goal}.”`);lines.push(`Your current monthly surplus is ${fmt(surplus,p)}. Ask me about investing, debt, emergency funds, retirement, budgeting, or a market drop and I’ll calculate it from your information.`);}
 return lines.join('\n\n')+'\n\nEducational guidance only. Assumptions may change and returns are not guaranteed.';
}


type UIAction={type:string;payload?:any};
function ActionModal({action,onClose,onNavigate,profile,onAsk}:{action:UIAction;onClose:()=>void;onNavigate:(t:Tab)=>void;profile:Profile;onAsk:(q:string)=>void}){
 const [email,setEmail]=useState('');const [frequency,setFrequency]=useState('weekly');const [status,setStatus]=useState('');const [query,setQuery]=useState('');useEffect(()=>{if(action.type==='Notifications')api<any>('/notifications').then(n=>{setEmail(n.email||'');setFrequency(n.frequency||'weekly')}).catch(()=>{})},[action.type]);
 const subscribe=async()=>{if(!email.includes('@')){setStatus('Enter a valid email address.');return}setStatus('Saving…');try{const d=await api<any>('/notifications',json('PUT',{email,frequency,enabled:true,locale:localStorage.getItem('swa-language')||'en'}));if('Notification' in window&&Notification.permission==='default')await Notification.requestPermission();setStatus(d.delivery_available?'Schedule saved. Email delivery is configured.':'Schedule saved. SMTP must be configured for email delivery.')}catch(e){setStatus(e instanceof Error?e.message:'Could not save right now.')}};
 const report=action.payload||{};const options:Tab[]=['Dashboard','Transactions','Budget','Insights','Guidance','Portfolio','Projects','Goals','Simulator','Calculators','Reports'];
 return <div className="actionOverlay" onClick={onClose}><div className="actionModal card" onClick={e=>e.stopPropagation()}><button className="detailClose" onClick={onClose}><X/></button>
 {action.type==='Search'?<><span className="eyebrow"><Search/> QUICK NAVIGATION</span><h2>Where do you want to go?</h2><input className="actionInput" autoFocus placeholder="Search pages and tools…" value={query} onChange={e=>setQuery(e.target.value)}/><div className="searchResults">{options.filter(x=>x.toLowerCase().includes(query.toLowerCase())).map(x=><button key={x} onClick={()=>{onNavigate(x);onClose()}}><span>{x}</span><ChevronRight/></button>)}</div></>:
 action.type==='Notifications'?<><span className="eyebrow"><Bell/> SMART ALERTS</span><h2>Periodic financial check-ins</h2><p>Receive cash-flow, goal, portfolio-risk and plan reminders by email. Your password is never requested.</p><label className="field"><span>Gmail or email address</span><input className="actionInput" type="email" placeholder="you@gmail.com" value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="field"><span>Frequency</span><select value={frequency} onChange={e=>setFrequency(e.target.value)}><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select></label><button className="primary modalPrimary" onClick={subscribe}><Bell/>Activate alerts</button>{status&&<div className="statusBox">{status}</div>}<small className="modalNote">Automatic delivery requires PostgreSQL plus SMTP settings on the server. Browser alerts are requested on this device.</small></>:
 action.type==='View report'?<><span className="eyebrow"><FileText/> FINANCIAL REPORT</span><h2>{report.name}</h2><p>{report.description}</p><div className="reportPreview"><b>Current snapshot</b><span>Net worth: {fmt(profile.capital+profile.savings-profile.debt,profile)}</span><span>Monthly surplus: {fmt(profile.income-profile.expenses,profile)}</span><span>Risk profile: {profile.risk}</span><span>Primary goal: {profile.goal}</span></div><button className="primary modalPrimary" onClick={()=>downloadFile(`${report.name||'report'}.txt`,`${report.name}\n\n${report.description}\n\nNet worth: ${fmt(profile.capital+profile.savings-profile.debt,profile)}\nMonthly surplus: ${fmt(profile.income-profile.expenses,profile)}\nRisk profile: ${profile.risk}\nGoal: ${profile.goal}\n\nEducational guidance only.`)}><Download/>Download report</button></>:
 action.type==='Disclosures'?<><span className="eyebrow"><ShieldCheck/> IMPORTANT INFORMATION</span><h2>Educational guidance and risk</h2><p>Smart Wealth Advisor provides educational planning scenarios. It does not guarantee returns and does not replace regulated investment, tax, or legal advice. Markets can fall and you may lose principal. Calculations depend on the data and assumptions you provide.</p><div className="statusBox">AI answers may be incomplete. Verify material decisions with qualified professionals in your country.</div></>:
 <><span className="eyebrow"><Sparkles/> SMART ACTION</span><h2>{action.type}</h2><p>{action.type==='Add a goal'?'Create and refine a goal with the AI advisor, including target amount, timeline and monthly contribution.':action.type==='Rebalance portfolio'?'Review allocation drift, tax impact and transaction costs before making any trade.':action.type==='Generate report'?'Generate a personalized report using your current profile and assumptions.':'This action is ready to continue with your saved financial profile.'}</p><button className="primary modalPrimary" onClick={()=>{onAsk(`${action.type}. Use my saved profile, ask for any missing information, and give me the next actionable steps.`);onClose()}}><Sparkles/>Continue with AI</button></>}
 </div></div>
}

type AIAction={type:'update_profile'|'navigate'|'save_goal'|'set_alert'|'add_transaction'|'update_budget';label?:string;reason?:string;payload?:Record<string,unknown>;target?:Tab;applied?:boolean};
type Msg={role:'user'|'ai';text:string;actions?:AIAction[]};
export default function App(){
 const translatedNodes=useRef(new Map<Node,string>());const translatedAttrs=useRef(new Map<Element,Record<string,string>>());const [profile,setProfile]=useState<Profile|null>(null);const [authenticated,setAuthenticated]=useState(false);const [authChecked,setAuthChecked]=useState(false);const [ready,setReady]=useState(false);const [languageChosen,setLanguageChosen]=useState(false);const [tab,setTab]=useState<Tab>('Dashboard');const [dark,setDark]=useState(false);const [ar,setAr]=useState(false);const [menu,setMenu]=useState(false);const [chat,setChat]=useState(false);const [input,setInput]=useState('');const [messages,setMessages]=useState<Msg[]>([]);const [uiAction,setUiAction]=useState<UIAction|null>(null);const [aiLoading,setAiLoading]=useState(false);const [aiMode,setAiMode]=useState<'cloud'|'local'>('cloud');const [memoryMode,setMemoryMode]=useState<'postgres'|'client'>('client');
 useEffect(()=>{try{const language=localStorage.getItem('swa-language');if(language==='ar'){setAr(true);setLanguageChosen(true)}else if(language==='en')setLanguageChosen(true)}catch{}const handler=(e:Event)=>setUiAction((e as CustomEvent).detail);window.addEventListener('swa-action',handler);setReady(true);return()=>window.removeEventListener('swa-action',handler)},[]);
 const hydrate=async()=>{try{const u=await api<any>('/auth/me');setAuthenticated(true);if(u.onboarding_complete){const s=await api<any>('/financial-summary');setProfile({name:u.name,age:u.age||30,country:u.country||'Egypt',currency:u.currency||'EGP',employment:u.employment||'Employed',capital:Math.max(0,Number(s.account_assets||0)-Number(s.liquid_savings||0)),income:Number(s.total_income||0),expenses:Number(s.total_expenses||0),savings:Number(s.liquid_savings||0),debt:Number(s.outstanding_debt||0),goal:'Build long-term wealth',horizon:u.investment_horizon||10,risk:u.risk_preference||'Balanced',essentialExpenses:Number(s.essential_expenses||0),emergencyFundMonths:s.emergency_fund_months==null?null:Number(s.emergency_fund_months),netWorth:Number(s.net_worth||0),monthlyDebtPayments:Number(s.monthly_debt_payments||0),debtToIncome:s.debt_to_income_ratio==null?null:Number(s.debt_to_income_ratio),portfolioValue:Number(s.portfolio_value||0),totalAssets:Number(s.total_assets||0)})}else setProfile(null)}catch{setAuthenticated(false);setProfile(null)}finally{setAuthChecked(true)}};
 useEffect(()=>{if(languageChosen)hydrate()},[languageChosen]);
 useEffect(()=>{document.documentElement.lang=ar?'ar':'en';document.documentElement.dir=ar?'rtl':'ltr';let observer:MutationObserver|undefined;
  const translateText=(node:Node)=>{const raw=node.textContent||'';const clean=raw.trim();const value=arabicUI[clean];if(value){if(!translatedNodes.current.has(node))translatedNodes.current.set(node,raw);node.textContent=raw.replace(clean,value)}};
  const scan=(root:Node)=>{if(root.nodeType===Node.TEXT_NODE){translateText(root);return}if(!(root instanceof Element||root instanceof Document))return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n:Node|null;while(n=walker.nextNode())translateText(n);if(root instanceof Element){const all=[root,...Array.from(root.querySelectorAll('input,textarea'))];for(const el of all){const ph=el.getAttribute('placeholder');if(ph&&arabicUI[ph]){if(!translatedAttrs.current.has(el))translatedAttrs.current.set(el,{placeholder:ph});el.setAttribute('placeholder',arabicUI[ph])}}}};
  if(ar){setTimeout(()=>scan(document.body),0);observer=new MutationObserver(items=>items.forEach(x=>x.addedNodes.forEach(scan)));observer.observe(document.body,{childList:true,subtree:true,characterData:true})}else{translatedNodes.current.forEach((v,n)=>{if(n.isConnected)n.textContent=v});translatedNodes.current.clear();translatedAttrs.current.forEach((attrs,el)=>{if(el.isConnected)Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v))});translatedAttrs.current.clear()}
  return()=>observer?.disconnect()
 },[ar]);

 const chooseLanguage=(language:'en'|'ar')=>{localStorage.setItem('swa-language',language);setAr(language==='ar');setLanguageChosen(true)};
 const toggleLanguage=()=>chooseLanguage(ar?'en':'ar');
 const complete=async(p:Profile)=>{await api('/profile',json('PUT',{name:p.name,locale:ar?'ar':'en',country:p.country,currency:p.currency,age:p.age,employment:p.employment,risk_preference:p.risk,investment_horizon:p.horizon,onboarding_complete:true}));const today=new Date().toISOString().slice(0,10);if(p.income>0)await api('/transactions',json('POST',{kind:'income',amount:p.income,currency:p.currency,occurred_on:today,description:ar?'الدخل الشهري الافتتاحي':'Opening monthly income',category:'Salary',recurring:true,tags:['onboarding']}));if(p.expenses>0)await api('/transactions',json('POST',{kind:'expense',amount:p.expenses,currency:p.currency,occurred_on:today,description:ar?'المصروفات الشهرية الافتتاحية':'Opening monthly expenses',category:'Other',recurring:true,tags:['onboarding']}));if(p.debt>0)await api('/liabilities',json('POST',{name:ar?'الديون الافتتاحية':'Opening liabilities',kind:'other',balance:p.debt,monthly_payment:0,interest_rate:0,currency:p.currency}));const accounts=await api<any[]>('/accounts');const primary=accounts[0];if(primary)await api(`/accounts/${primary.id}`,json('PATCH',{balance:p.savings,is_liquid:true,emergency_eligible:true}));if(p.capital>0)await api('/accounts',json('POST',{name:ar?'رأس المال المتاح':'Available capital',kind:'other',currency:p.currency,balance:p.capital,is_liquid:false,emergency_eligible:false,active:true}));await api('/goals',json('POST',{name:p.goal,target_amount:Math.max(p.savings*2,p.savings+1,1),current_amount:0,currency:p.currency,priority:1}));setProfile(p)};
 const reset=()=>{if(confirm(ar?'هل تريد تعديل ملفك المالي؟':'Edit your financial profile?'))setProfile(null)};
 const logout=async()=>{await api('/auth/logout',json('POST',{})).catch(()=>{});setAuthenticated(false);setProfile(null);setMessages([])};
 const send=async(text=input)=>{const q=text.trim();if(!q||!profile||aiLoading)return;const next=[...messages,{role:'user' as const,text:q}];setMessages(next);setInput('');setAiLoading(true);setChat(true);try{const res=await fetch('/api/advisor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,locale:ar?'ar':'en'})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data?.error?.message||'AI unavailable');setMessages([...next,{role:'ai' as const,text:data.answer,actions:Array.isArray(data.actions)?data.actions:[]}]);setAiMode('cloud');setMemoryMode(data.memory==='postgres'?'postgres':'client')}catch(error){const reason=error instanceof Error?error.message:'';setMessages([...next,{role:'ai' as const,text:ar?`تعذر تشغيل المستشار الآن${reason?` (${reason})`:''}. لم يتم إنشاء رد بديل أو بيانات مزيفة.`:`The advisor is unavailable${reason?` (${reason})`:''}. No canned response or fabricated data was substituted.`}]);setAiMode('local')}finally{setAiLoading(false)}};
 const applyAIAction=async(action:AIAction,messageIndex:number,actionIndex:number)=>{if(!profile||action.applied)return;if(action.type==='navigate'&&action.target){setTab(action.target);return}try{const prepared=await api<any>('/ai-actions/prepare',json('POST',{action:{type:action.type,payload:action.payload||{}}}));const detail=JSON.stringify(prepared.action.payload,null,2);const ok=confirm((ar?'راجع التعديل التالي ثم أكّد التطبيق:\n':'Review the exact change, then confirm:\n')+detail);if(!ok)return;await api('/ai-actions/execute',json('POST',{action:prepared.action,confirmation_token:prepared.confirmation_token}));if(action.type==='add_transaction'){window.dispatchEvent(new Event('swa-data-updated'));setTab('Transactions')}else if(action.type==='update_budget')setTab('Budget');else if(action.type==='save_goal')setTab('Goals');await hydrate();setMessages(current=>{const copy=current.map(m=>({...m,actions:m.actions?.map(a=>({...a}))}));if(copy[messageIndex]?.actions?.[actionIndex])copy[messageIndex].actions![actionIndex].applied=true;return copy})}catch(e){alert(e instanceof Error?e.message:(ar?'تعذر تطبيق الإجراء':'Could not apply action'))}};


 if(!ready)return <main className="loading"><Logo/></main>;
 if(!languageChosen)return <LanguageGate onSelect={chooseLanguage}/>;
 if(!authChecked)return <main className="loading"><Logo/></main>;
 if(!authenticated)return <AuthScreen ar={ar} onAuthenticated={hydrate}/>;
 if(!profile)return <Onboarding onComplete={complete}/>;
 const initials=profile.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();
 return <main className={`${dark?'dark':''} ${ar?'rtl':''}`} dir={ar?'rtl':'ltr'}>
 <aside className={menu?'open':''}><div className="asideTop"><Logo/><button className="close" onClick={()=>setMenu(false)}><X/></button></div><nav><span>OVERVIEW</span>{nav.map(([name,Icon])=><button key={name} className={tab===name?'active':''} onClick={()=>{setTab(name);setMenu(false)}}><Icon/>{name}<ChevronRight className="chev"/></button>)}</nav><div className="sideBottom"><button onClick={()=>setChat(true)}><span><MessageCircle/></span><div><b>AI Financial Advisor</b><small>Uses your financial profile</small></div><i/></button><button onClick={reset}><Settings/><span>Edit financial profile</span></button><button onClick={logout}><ShieldCheck/><span>{ar?'تسجيل الخروج':'Sign out'}</span></button><div className="profile"><div>{initials}</div><p><b>{profile.name}</b><small>{ar?`${arabicUI[profile.risk]||profile.risk} · خطة تعليمية`:`${profile.risk} plan`}</small></p><ChevronDown/></div></div></aside>
 <div className="app"><header><button className="menu" onClick={()=>setMenu(true)}><Menu/></button><div className="crumb"><span>Smart Wealth</span><ChevronRight/><b>{tab}</b></div><div className="headActions"><button className="search" onClick={()=>act('Search')}><Search/><span>Search anything…</span><kbd>⌘ K</kbd></button><button className="round" onClick={toggleLanguage}>{ar?'EN':'ع'}</button><button className="round" onClick={()=>setDark(!dark)}>{dark?<Sun/>:<Moon/>}</button><button className="round notify" onClick={()=>act('Notifications')}><Bell/><i/></button><button className="avatar" onClick={()=>act('Profile')}>{initials}</button></div></header>
 <div className="content">{tab==='Dashboard'?<Dashboard ar={ar} setTab={setTab} profile={profile}/>:tab==='Transactions'?<TransactionsPage profile={profile} ar={ar}/>:tab==='Budget'?<BudgetPage profile={profile} ar={ar}/>:tab==='Insights'?<AnalyticsPage profile={profile} ar={ar}/>:tab==='Guidance'?<GuidancePage profile={profile} ar={ar} onAsk={(q)=>send(q)}/>:tab==='Portfolio'?<Portfolio profile={profile} ar={ar}/>:tab==='Projects'?<Projects profile={profile} onAsk={(q)=>send(q)}/>:tab==='Goals'?<Goals profile={profile} ar={ar}/>:tab==='Simulator'?<Simulator profile={profile}/>:tab==='Calculators'?<Calculators/>:<Reports profile={profile} ar={ar}/>}</div><footer><ShieldCheck/> Educational guidance only — not a guarantee of returns or individualized tax or legal advice. <button onClick={()=>act('Disclosures')}>Read disclosures</button></footer></div>
 <button className="floatingChat" onClick={()=>setChat(true)}><Sparkles/><span>Ask AI</span></button>
 {chat&&<div className="overlay" onClick={()=>setChat(false)}><div className="chatPanel" onClick={e=>e.stopPropagation()}><div className="chatHead"><div><span><Sparkles/></span><div><b>{ar?'مستشار الثروة':'Wealth Advisor'}</b><small><i/> {aiMode==='cloud'?`Gemini AI · ${memoryMode==='postgres'?(ar?'ذاكرة PostgreSQL':'PostgreSQL memory'):(ar?'بانتظار اتصال آمن':'Awaiting secure connection')}`:(ar?'المستشار غير متاح':'Advisor unavailable')} </small></div></div><div className="chatHeadBtns"><button title="New conversation" onClick={()=>setMessages([])}><Trash2/></button><button title="Close" onClick={()=>setChat(false)}><X/></button></div></div><div className="chatBody"><span className="date">{ar?'مخصص لـ':'PERSONALIZED FOR'} {profile.name.toUpperCase()}</span><div className="aiMsg">{ar?`مرحبًا ${profile.name} — راجعت بياناتك المالية. فائضك الشهري الحالي هو `:`Hi ${profile.name} — I’ve reviewed your financial information. Your current monthly surplus is `}<b>{fmt(profile.income-profile.expenses,profile)}</b>{ar?'، ماذا تريد أن نحلل؟':' What would you like to explore?'}<small>{aiMode==='cloud'?(memoryMode==='postgres'?(ar?'ذكاء اصطناعي حقيقي · ذاكرة خادم مستمرة':'Real AI · Persistent server memory'):(ar?'لم يتم إرسال طلب بعد':'No request sent yet')):(ar?'غير متاح · لم يُنشأ رد بديل':'Unavailable · no substitute response generated')}</small></div>{messages.map((m,i)=><div key={i} className={m.role==='user'?'userMsg':'aiMsg'}>{m.text.split('\n').map((l,j)=><span key={j}>{l||<br/>}</span>)}{m.role==='ai'&&m.actions?.map((a,j)=><div className={`aiAction ${a.applied?'applied':''}`} key={j}><div><b>{a.label||(ar?'تعديل مقترح':'Suggested change')}</b>{a.reason&&<small>{a.reason}</small>}</div><button disabled={a.applied} onClick={()=>applyAIAction(a,i,j)}>{a.applied?(ar?'تم التطبيق':'Applied'):(ar?'مراجعة وتطبيق':'Review & apply')}</button></div>)}</div>)}{aiLoading&&<div className="thinking"><i/><i/><i/><span>Thinking through your plan…</span></div>}{messages.length===0&&<div className="prompts">{(ar?['كيف أستثمر رأس المال المتاح؟','هل أستطيع التقاعد بشكل مريح؟','اختبر تأثير هبوط السوق 20٪','كيف أحسن معدل الادخار؟']:['How should I invest my available capital?','Can I retire comfortably?','Stress-test a 20% market drop','How can I improve my savings rate?']).map(x=><button key={x} onClick={()=>send(x)}>{x}</button>)}</div>}</div><div className="chatInput"><button onClick={()=>act('Attach financial document')}><Plus/></button><input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder="Ask about your money…"/><button className="send" onClick={()=>send()}><Send/></button></div></div></div>}
 {uiAction&&<ActionModal action={uiAction} onClose={()=>setUiAction(null)} onNavigate={setTab} profile={profile} onAsk={(q)=>send(q)}/>}
 </main>
}
